"#include <metal_stdlib>
using namespace metal;

struct VertexOut {
    float4 renderedCoordinate [[position]];
    float2 textureCoordinate;
};

struct TransformUniforms {
    int rotation;
    int flipH;
    int flipV;
    int padding;
};

vertex VertexOut mapTexture(uint vertexID [[vertex_id]], constant TransformUniforms& transform [[buffer(0)]]) {
    const float2 pos[4] = { float2(-1.0, 1.0), float2(1.0, 1.0), float2(-1.0, -1.0), float2(1.0, -1.0) };
    float2 uv[4];
    int rot = transform.rotation;
    if (rot == 90) {
        uv[0] = float2(0.0, 1.0);
        uv[1] = float2(0.0, 0.0);
        uv[2] = float2(1.0, 1.0);
        uv[3] = float2(1.0, 0.0);
    } else if (rot == 180) {
        uv[0] = float2(1.0, 1.0);
        uv[1] = float2(0.0, 1.0);
        uv[2] = float2(1.0, 0.0);
        uv[3] = float2(0.0, 0.0);
    } else if (rot == 270) {
        uv[0] = float2(1.0, 0.0);
        uv[1] = float2(1.0, 1.0);
        uv[2] = float2(0.0, 0.0);
        uv[3] = float2(0.0, 1.0);
    } else {
        uv[0] = float2(0.0, 0.0);
        uv[1] = float2(1.0, 0.0);
        uv[2] = float2(0.0, 1.0);
        uv[3] = float2(1.0, 1.0);
    }
    float2 finalPos = pos[vertexID];
    if (transform.flipH != 0) {
        finalPos.x = -finalPos.x;
    }
    if (transform.flipV != 0) {
        finalPos.y = -finalPos.y;
    }
    VertexOut out;
    out.renderedCoordinate = float4(finalPos, 0.0, 1.0);
    out.textureCoordinate = uv[vertexID];
    return out;
}

struct ChannelReshape {
    float4 pivots_0_3;
    float4 pivots_4_7;
    float4 pivot_8_info;
    float4 coeffs_0;
    float4 coeffs_1;
    float4 coeffs_2;
    float4 coeffs_3;
    float4 coeffs_4;
    float4 coeffs_5;
    float4 coeffs_6;
    float4 coeffs_7;
};

struct DolbyVisionReshapeUniforms {
    float4 nonlinear_offset;
    float3x3 nonlinear_matrix;
    float3x3 linear_matrix;
    ChannelReshape ch0;
    ChannelReshape ch1;
    ChannelReshape ch2;
};

inline float evaluateReshape(constant ChannelReshape& ch, float s) {
    uint num_pivots = uint(ch.pivot_8_info.y);
    float lo = ch.pivots_0_3.x;
    float hi = ch.pivot_8_info.x;
    if (num_pivots <= 2) {
        float4 c = ch.coeffs_0;
        float res = (c.z * s + c.y) * s + c.x;
        return clamp(res, lo, hi);
    }

    float4 c;
    if (s < ch.pivots_0_3.y) {
        c = ch.coeffs_0;
    } else if (s < ch.pivots_0_3.z) {
        c = ch.coeffs_1;
    } else if (s < ch.pivots_0_3.w) {
        c = ch.coeffs_2;
    } else if (s < ch.pivots_4_7.x) {
        c = ch.coeffs_3;
    } else if (s < ch.pivots_4_7.y) {
        c = ch.coeffs_4;
    } else if (s < ch.pivots_4_7.z) {
        c = ch.coeffs_5;
    } else if (s < ch.pivots_4_7.w) {
        c = ch.coeffs_6;
    } else {
        c = ch.coeffs_7;
    }
    float res = (c.z * s + c.y) * s + c.x;
    return clamp(res, lo, hi);
}

inline float3 doviP5Linearize(float3 v) {
    const float m1 = 2610.0 / 16384.0;
    const float m2 = 2523.0 * 128.0 / 4096.0;
    const float c1 = 3424.0 / 4096.0;
    const float c2 = 2413.0 * 32.0 / 4096.0;
    const float c3 = 2392.0 * 32.0 / 4096.0;

    float3 v_pos = max(v, 0.0);
    float3 vp = pow(v_pos, 1.0 / m2);
    float3 num = max(vp - c1, 0.0);
    float3 den = max(c2 - c3 * vp, 1e-6);
    return pow(num / den, 1.0 / m1);
}

// BT.2390-style highlight rolloff: diffuse range [0, 1] is 1:1 preserved without compression
inline float doviToneMap(float x) {
    if (x <= 1.0) return x;
    float excess = x - 1.0;
    return 1.0 + excess / (1.0 + excess * 0.7);
}

// Standard Display P3 / sRGB parametric OETF (linear toe prevents crushed shadow details)
inline float doviToP3(float c) {
    c = clamp(c, 0.0, 1.0);
    return (c <= 0.0031308) ? (12.92 * c) : (1.055 * pow(c, 1.0 / 2.4) - 0.055);
}

inline half4 doviP5Process(float I_raw, float Cb_raw, float Cr_raw,
                           constant DolbyVisionReshapeUniforms& dovi)
{
    // Clamp raw input to [0.0, 1.0] before reshaping (matches libplacebo: sig = clamp(color.rgb, 0.0, 1.0))
    I_raw  = clamp(I_raw,  0.0, 1.0);
    Cb_raw = clamp(Cb_raw, 0.0, 1.0);
    Cr_raw = clamp(Cr_raw, 0.0, 1.0);

    // 2. Reshape channels dynamically according to stream RPU metadata:
    // comp 0 = Y (Luma I), comp 1 = Cb (Tritan T), comp 2 = Cr (Protan P)
    float I_reshaped  = evaluateReshape(dovi.ch0, I_raw);
    float Cb_reshaped = evaluateReshape(dovi.ch1, Cb_raw);
    float Cr_reshaped = evaluateReshape(dovi.ch2, Cr_raw);

    // 3. Subtract signaled color offsets (dovi.nonlinear_offset.xyz, typically [0.0, 0.5, 0.5])
    float3 ycc = float3(I_reshaped, Cb_reshaped, Cr_reshaped) - dovi.nonlinear_offset.xyz;

    // 4. Transform YCC -> LMS' (non-linear LMS) using signaled nonlinear matrix (ycc_to_rgb_matrix)
    float3 lms_prime = dovi.nonlinear_matrix * ycc;

    // 5. Inverse PQ Transfer Function (SMPTE ST 2084 EOTF to linear light)
    float3 lms_linear = doviP5Linearize(lms_prime);

    // 6. Linear LMS to Linear Display P3 (precomputed on CPU: rec2020_to_p3 * dovi_lms2rgb * rgb_to_lms)
    float3 rgb_p3 = dovi.linear_matrix * lms_linear;
    rgb_p3 = max(rgb_p3, 0.0);

    // 7. Reference White Scaling for macOS EDR:
    // In extendedLinearDisplayP3, 1.0 represents SDR diffuse white (203 nits in BT.2408).
    // Specular highlights up to 10000 nits scale linearly (> 1.0 up to 49.26).
    // macOS Metal EDR compositor maps values > 1.0 directly to display panel peak headroom!
    float3 linear_p3 = rgb_p3 * (10000.0 / 203.0);
    return half4(half3(linear_p3), 1.0);
}

fragment half4 displayDoviP5(VertexOut in [[ stage_in ]],
                             texture2d<float> lumaTexture [[ texture(0) ]],
                             texture2d<float> chromaTexture [[ texture(1) ]],
                             sampler textureSampler [[ sampler(0) ]],
                             constant DolbyVisionReshapeUniforms& dovi [[ buffer(0) ]])
{
    float I_raw = lumaTexture.sample(textureSampler, in.textureCoordinate).r;
    float2 chroma = chromaTexture.sample(textureSampler, in.textureCoordinate).rg;
    return doviP5Process(I_raw, chroma.x, chroma.y, dovi);
}

fragment half4 displayStandardNV12(VertexOut in [[ stage_in ]],
                                   texture2d<float> lumaTexture [[ texture(0) ]],
                                   texture2d<float> chromaTexture [[ texture(1) ]],
                                   sampler textureSampler [[ sampler(0) ]],
                                   constant float3x3& yuvToRGB [[ buffer(0) ]],
                                   constant float3& colorOffset [[ buffer(1) ]])
{
    float y = lumaTexture.sample(textureSampler, in.textureCoordinate).r;
    float2 uv = chromaTexture.sample(textureSampler, in.textureCoordinate).rg;
    float3 yuv = float3(y, uv.x, uv.y) + colorOffset;
    float3 rgb = max(yuvToRGB * yuv, 0.0);
    return half4(half3(rgb), 1.0);
}

constant float3x3 kRec2020_to_P3 = float3x3(
    float3( 1.343579, -0.065296,  0.002822),
    float3(-0.282180,  1.075788, -0.041261),
    float3(-0.061399, -0.010492,  1.038439)
);

fragment half4 displayHDR10(VertexOut in [[ stage_in ]],
                            texture2d<float> lumaTexture [[ texture(0) ]],
                            texture2d<float> chromaTexture [[ texture(1) ]],
                            sampler textureSampler [[ sampler(0) ]])
{
    float y_raw = lumaTexture.sample(textureSampler, in.textureCoordinate).r;
    float2 uv_raw = chromaTexture.sample(textureSampler, in.textureCoordinate).rg;

    // BT.2020 Limited Video Range normalization
    float y = (y_raw - (16.0 / 255.0)) * (255.0 / 219.0);
    float u = (uv_raw.x - (128.0 / 255.0)) * (255.0 / 224.0);
    float v = (uv_raw.y - (128.0 / 255.0)) * (255.0 / 224.0);

    // Rec.2020 YUV to non-linear RGB
    float r_prime = clamp(y + 1.47460 * v, 0.0, 1.0);
    float g_prime = clamp(y - 0.16455 * u - 0.57135 * v, 0.0, 1.0);
    float b_prime = clamp(y + 1.88140 * u, 0.0, 1.0);

    // SMPTE ST 2084 PQ EOTF (Linearize in 10000 nits space)
    float3 rgb_linear_2020 = doviP5Linearize(float3(r_prime, g_prime, b_prime));

    // Gamut Conversion: Linear Rec.2020 -> Linear Display P3
    float3 rgb_linear_p3 = max(kRec2020_to_P3 * rgb_linear_2020, 0.0);

    // Diffuse White Scaling for macOS EDR (1.0 = 203 nits SDR white, > 1.0 = HDR specular highlights)
    float3 linear_p3 = rgb_linear_p3 * (10000.0 / 203.0);
    return half4(half3(linear_p3), 1.0);
}"
